122	/**
123	 * If a GAME OsTemplate's setupScript installs the game via a detached
124	 * `docker run -d --name <container> ...` (true for every game image today —
125	 * see the OsTemplate rows for minecraft/terraria/ark/etc., all `docker run -d`),
126	 * rewrite the invocation to `docker create` and append a generated systemd unit
127	 * that starts/stops the container.
128	 *
129	 * WHY THIS EXISTS: the whole game control panel — GAME_POWER start/stop/restart,
130	 * GAME_BACKUP, log tailing (lib/game-control.ts + worker/game-control.ts) —
131	 * resolves the running game exclusively via `systemctl cat <serviceHint>` /
132	 * `journalctl -u <unit>`. A bare `docker run -d` creates no systemd unit at all,
133	 * so every one of those lookups comes back empty and every control action fails
134	 * silently, on every game family, on every order. Found 2026-08-26 diagnosing a
135	 * customer's Terraria server (cmt9ss7ln000xhlrx0gch9fcx) that could never be
136	 * started/stopped from the dashboard even though PROVISION had completed
137	 * successfully — the container was in fact running, just entirely invisible to
138	 * systemd.
139	 *
140	 * The generated unit is named after the family's FIRST serviceHint, not the
141	 * docker container's own `--name` — the two don't always match (minecraft's
142	 * image runs as container "mc" but its control-spec hints are "minecraft" /
143	 * "minecraft-server") — so `systemctl cat <hint>` resolves regardless of what an
144	 * individual image's setup script happened to call its container.
145	 *
146	 * Intentionally conservative: any setupScript that doesn't match the exact
147	 * `docker run -d --name X ...` shape (or any non-game family, e.g. the
148	 * LAMP/WordPress/Caddy panel images that already install a real native systemd
149	 * service) is returned completely unchanged.
150	 */
151	function wrapDockerGameService(setupScript: string, family: string | null): string {
152	  if (!isGameFamily(family)) return setupScript;
153	  const unitName = controlSpec(family)?.serviceHints[0];
154	  if (!unitName) return setupScript;
155	
156	  const re = /docker run\s+(?:-d|--detach)\b(.*?)\s+--name[= ]("?)([A-Za-z0-9_.-]+)\2(.*)$/.exec(setupScript.trim());
157	  if (!re) return setupScript;
158	  const [full, before, , containerName, after] = re;
159	  const matchIndex = setupScript.indexOf(full);
160	  if (matchIndex < 0) return setupScript;
161	
162	  // Strip docker's own restart policy — systemd now owns restart semantics for
163	  // this container, and leaving both in place makes the two supervisors fight
164	  // over a crash-looping process.
165	  const cleanedAfter = after.replace(/\s*--restart(?:=|\s+)\S+/, "");
166	  const createCmd = `docker create --name ${containerName}${before}${cleanedAfter}`.replace(/\s+/g, " ").trim();
167	
168	  const prefix = setupScript.slice(0, matchIndex);
169	  const unit = [
170	    `cat > /etc/systemd/system/${unitName}.service <<'NXUNIT'`,
171	    "[Unit]",
172	    `Description=Nxeon game service (docker: ${containerName})`,
173	    "After=docker.service",
174	    "Requires=docker.service",
175	    "",
176	    "[Service]",
177	    `ExecStart=/usr/bin/docker start -a ${containerName}`,
178	    `ExecStop=/usr/bin/docker stop -t 30 ${containerName}`,
179	    "Restart=always",
180	    "RestartSec=5",
181	    "TimeoutStartSec=0",
182	    "",
183	    "[Install]",
184	    "WantedBy=multi-user.target",
185	    "NXUNIT",
186	    "systemctl daemon-reload",
187	    `systemctl enable --now ${unitName}`,
188	  ].join("\n");
189	
190	  return `${prefix}${createCmd}\n${unit}`;
191	}
