193	/**
194	 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
195	 * plus any control-panel/app install script and selected add-ons. Long installs
196	 * run in the background so the VM reports ready promptly.
197	 */
198	/**
199	 * The nxeon-shipper install: fetch the static binary, drop its config (server
200	 * id + per-server token minted by the caller, see provision()), install the
201	 * systemd unit, and start it. Idempotent (safe to re-run on a retried
202	 * provision) and — like the Claude CLI install — backgrounded via the outer
203	 * nohup so a slow/blocked download never delays the VM reporting ready.
204	 *
205	 * `curl -fsSL … | sh`-style external installs are the established convention
206	 * here (see get.docker.com / claude.ai/install.sh above); this one pulls from
207	 * our own APP_URL instead of a third party since the binary is ours.
208	 */
209	function shipperInstallScript(serverId: string, token: string, nodeKind: "VPS" | "GAME"): string {
210	  const appUrl = process.env.APP_URL ?? "https://nxeon.cloud";
211	  const config = JSON.stringify({
212	    server_id: serverId,
213	    token,
214	    ingest_url: `${appUrl}/api/telemetry/ingest`,
215	    node_kind: nodeKind,
216	  });
217	  return [
218	    "mkdir -p /etc/nxeon",
219	    `cat > /etc/nxeon/shipper.json <<'NXTJSON'\n${config}\nNXTJSON`,
220	    "chmod 600 /etc/nxeon/shipper.json",
221	    `curl -fsSL "${appUrl}/dl/nxeon-shipper-linux-amd64" -o /usr/local/bin/nxeon-shipper.tmp && ` +
222	      "chmod +x /usr/local/bin/nxeon-shipper.tmp && mv /usr/local/bin/nxeon-shipper.tmp /usr/local/bin/nxeon-shipper",
223	    `curl -fsSL "${appUrl}/dl/nxeon-shipper.service" -o /etc/systemd/system/nxeon-shipper.service`,
224	    "systemctl daemon-reload && systemctl enable --now nxeon-shipper",
225	  ].join("\n");
226	}
