228	function buildCloudInit(server: any): string {
229	  const addons = (server.addons ?? {}) as {
230	    malwareScanner?: boolean;
231	    dailyBackup?: boolean;
232	    docker?: boolean;
233	    claudeCode?: boolean;
234	  };
235	  const setup: string[] = [];
236	
237	  // Pre-bake Claude Code (Anthropic CLI) on every server unless explicitly opted
238	  // out. Customers SSH in and run `claude` using their own subscription or API
239	  // key — no setup on our side, zero token cost to us. Installs run in the
240	  // background (nohup below) so the VM still reports ready quickly.
241	  if (addons.claudeCode !== false) {
242	    // Same steps the backfill (task #73) runs on existing servers — one source of
243	    // truth in lib/claude-install.ts, so cloud-init and backfill never drift.
244	    setup.push(...CLAUDE_CLI_INSTALL_STEPS);
245	  }
246	
247	  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
248	  if (addons.malwareScanner)
249	    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
250	  if (server.osTemplate.setupScript) {
251	    // Translate the customer's checkout-time variant choice (Server.gameVariant)
252	    // into the actual install command BEFORE wrapping it into a systemd unit —
253	    // see applyGameVariant for why this substitution didn't exist until now.
254	    const scriptWithVariant = applyGameVariant(server.osTemplate.setupScript, server.osTemplate.family, server.gameVariant);
255	    // Game images install as a bare `docker run -d` with no systemd unit, which
256	    // the game control panel (systemctl-based) can never see or manage — wrap it
257	    // in a generated unit so start/stop/restart/backup/logs actually work. See
258	    // wrapDockerGameService for the full story; a no-op for non-game templates.
259	    setup.push(wrapDockerGameService(scriptWithVariant, server.osTemplate.family));
260	  }
261	  // NxCloud: when this VM backs a managed Nextcloud instance, `provision` stashes
262	  // the per-instance install script here (admin creds injected). See worker/nxcloud.ts.
263	  if (server.__nxcloudSetup) setup.push(server.__nxcloudSetup);
264	
265	  // Live telemetry (see agent/nxeon-shipper + lib/telemetry-token.ts): `provision`
266	  // mints a per-server token and stashes it here, same convention as
267	  // __nxcloudSetup above, right before calling buildCloudInit(). Every VPS/game
268	  // server gets the shipper — there's no opt-out addon toggle for this one since
269	  // it's operational telemetry, not a customer-facing feature.
270	  if (server.__telemetryToken) {
271	    const kind: "VPS" | "GAME" = server.gamePlanId ? "GAME" : "VPS";
272	    setup.push(shipperInstallScript(server.id, server.__telemetryToken, kind));
273	  }
274	
275	  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
276	
277	  // Every VM gets a swapfile. A small plan (the 2 GB Starter is the common one)
278	  // with ZERO swap OOM-kills under any spike — a container image build, a traffic
279	  // burst, a migrated app's first request — and the kernel kills a process with no
280	  // warning and nothing to fall back on. A RAM-sized swapfile (capped so it never
281	  // eats a small root disk) turns a hard kill into slow-but-alive. Idempotent:
282	  // skips if any swap is already on or /swapfile already exists.
283	  const swapScript = [
284	    "#!/bin/bash",
285	    "# Nxeon: ensure a swapfile exists as an OOM safety net on small-RAM VMs.",
286	    "if swapon --show=NAME --noheadings 2>/dev/null | grep -q .; then exit 0; fi",
287	    "[ -e /swapfile ] && exit 0",
288	    'MEM_MB=$(awk "/MemTotal/{print int(\\$2/1024)}" /proc/meminfo 2>/dev/null || echo 1024)',
289	    "SWAP_MB=$MEM_MB",
290	    '[ "$SWAP_MB" -lt 1024 ] && SWAP_MB=1024',
291	    '[ "$SWAP_MB" -gt 4096 ] && SWAP_MB=4096',
292	    "# Leave >2 GB free on / so the swapfile never fills the root disk.",
293	    'AVAIL_MB=$(df -Pm / | awk "NR==2{print \\$4}")',
294	    '[ -n "$AVAIL_MB" ] && [ "$AVAIL_MB" -lt $((SWAP_MB + 2048)) ] && SWAP_MB=$((AVAIL_MB - 2048))',
295	    '[ "$SWAP_MB" -lt 256 ] && exit 0',
296	    "fallocate -l ${SWAP_MB}M /swapfile 2>/dev/null || dd if=/dev/zero of=/swapfile bs=1M count=${SWAP_MB} 2>/dev/null || exit 0",
297	    "chmod 600 /swapfile",
298	    "mkswap /swapfile >/dev/null 2>&1 || exit 0",
299	    "swapon /swapfile 2>/dev/null || exit 0",
300	    "grep -q '^/swapfile ' /etc/fstab 2>/dev/null || echo '/swapfile none swap sw 0 0' >> /etc/fstab",
301	    "grep -q '^vm.swappiness' /etc/sysctl.conf 2>/dev/null || { echo 'vm.swappiness=10' >> /etc/sysctl.conf; sysctl -w vm.swappiness=10 >/dev/null 2>&1 || true; }",
302	  ].join("\n");
303	
304	  // A friendly first-login guide + MOTD banner pointing at the portal hub.
305	  const welcome = [
306	    "# Welcome to your Nxeon server",
307	    "",
308	    "## Build anything with Claude Code — it's already installed",
309	    "",
310	    "1. You're already logged in. Just run:",
311	    "",
312	    "   claude",
313	    "",
314	    "2. Sign in once — either with your Claude subscription (Pro/Max) or an",
315	    "   Anthropic API key. See the step-by-step guide with screenshots at:",
316	    "",
317	    "   https://nxeon.cloud/dashboard/claude-code",
318	    "",
319	    "3. Then describe what you want in plain English, for example:",
320	    '   "Build a modern website for my coffee shop with a menu and contact form,',
321	    '    then run it and tell me the URL to preview it."',
322	    "",
323	    "Copy-paste starter prompts (spa site, booking app, REST API, Discord bot,",
324	    "and 20+ more) and how-to guides live in your portal at the link above.",
325	    "",
326	    "Happy building!",
327	  ].join("\n");
328	
329	  // Honest MOTD: check for the binary at login and only claim it's installed when
330	  // it really is. A failed background install must never greet the customer with
331	  // "Claude Code is pre-installed" and then 'command not found' — it tells them how
332	  // to install it instead.
333	  const motd = [
334	    "#!/bin/sh",
335	    'if [ -t 1 ]; then',
336	    '  if command -v claude >/dev/null 2>&1 || [ -x /usr/local/bin/claude ]; then',
337	    '    printf "\\n  \\033[1mNxeon\\033[0m — Claude Code is pre-installed on this server.\\n"',
338	    '    printf "  Run \\033[1mclaude\\033[0m to start building. Guide: https://nxeon.cloud/dashboard/claude-code\\n"',
339	    "  else",
340	    '    printf "\\n  \\033[1mNxeon\\033[0m — install Claude Code:  curl -fsSL https://claude.ai/install.sh | bash\\n"',
341	    '    printf "  Then run \\033[1mclaude\\033[0m. Guide: https://nxeon.cloud/dashboard/claude-code\\n"',
342	    "  fi",
343	    '  printf "  Full walkthrough: \\033[2m~/START-WITH-CLAUDE.md\\033[0m\\n\\n"',
344	    "fi",
345	  ].join("\n");
346	
347	  return `#cloud-config
348	package_update: true
349	packages:
350	  - qemu-guest-agent
351	ssh_pwauth: true
352	disable_root: false
353	write_files:
354	  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
355	    permissions: "0644"
356	    content: |
357	      PermitRootLogin yes
358	      PasswordAuthentication yes
359	  - path: /root/START-WITH-CLAUDE.md
360	    permissions: "0644"
361	    content: |
362	${indentBlock(welcome, 6)}
363	  - path: /etc/profile.d/nxeon-welcome.sh
364	    permissions: "0755"
365	    content: |
366	${indentBlock(motd, 6)}
367	  - path: /root/nxeon-swap.sh
368	    permissions: "0755"
369	    content: |
370	${indentBlock(swapScript, 6)}
371	  - path: /root/nxeon-setup.sh
372	    permissions: "0755"
373	    content: |
374	${indentBlock(script, 6)}
375	runcmd:
376	  - systemctl enable --now qemu-guest-agent
377	  - systemctl restart ssh || systemctl restart sshd
378	  - /root/nxeon-swap.sh > /var/log/nxeon-swap.log 2>&1 || true
379	  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
380	`;
381	}
382	
383	const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
384	const SNIPPET_STORAGE = process.env.NXEON_SNIPPET_STORAGE ?? "backup";
385	
386	/**
387	 * Allocate a vmid for a brand-new server, refusing any id that still owns backup
388	 * archives from a previous tenant (see `pickProvisionVmid` for the incident).
389	 *
390	 * If the archive listing cannot be read we do NOT silently fall back to the raw
391	 * `nextVmid()` — that is the exact behaviour that leaks a previous tenant's data,
392	 * and a provision that fails is recoverable while a cross-tenant disclosure is
393	 * not. The job retries; an operator sees why.
394	 */
395	async function allocateFreshVmid(conn: any): Promise<number> {
396	  const candidate = await conn.nextVmid();
397	  const archived = await archivedVmids(conn);
398	
399	  // Ids already in use, so skipping forward cannot land on a live VM. Read
400	  // cluster-wide (qemu + lxc); fall back to this node's qemu list.
401	  let taken = new Set<number>();
402	  try {
403	    const res: any[] = await conn.get("/cluster/resources", { type: "vm" });
404	    for (const r of res ?? []) if (Number.isInteger(r?.vmid)) taken.add(r.vmid);
405	  } catch {
406	    const vms: any[] = await conn.get(`/nodes/${conn.node}/qemu`);
407	    taken = new Set((vms ?? []).map((v: any) => Number(v?.vmid)).filter(Number.isInteger));
408	  }
409	
410	  const { vmid, skipped } = pickProvisionVmid({ candidate, takenVmids: taken, archivedVmids: archived });
411	  if (skipped.length > 0) {
412	    console.warn(
413	      `[worker] vmid ${skipped.join(", ")} skipped for provisioning — still holds backup archives ` +
414	        `from a previous server; allocated ${vmid} instead`
415	    );
416	  }
417	  return vmid;
418	}
