420	async function provision(job: Job) {
421	  const server = await loadServer(job);
422	  // Clear any stale failure reason from a previous attempt as this run starts, so
423	  // a successful retry doesn't leave the last error hanging around on the row.
424	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING", provisionError: null, provisioningStep: null } });
425	  // Best-effort, human-readable "what's happening right now" label for
426	  // <ProvisioningOverlay/> (lib/provisioning-step.ts) — written between the real,
427	  // observable checkpoints below (Proxmox clone/config/start, guest-agent boot,
428	  // SSH reachability, and the game's own port opening). Never allowed to fail
