900	async function reinstall(job: Job) {
901	  const server = await loadServer(job);
902	  if (SANDBOX) {
903	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
904	    await notify(
905	      server.userId,
906	      `Server ${server.hostname} reinstalled (sandbox)`,
907	      "The sandbox server was reinstalled (no real VM was touched).",
908	      `/dashboard/servers/${server.id}`
909	    );
910	    return;
911	  }
912	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
913	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
914	  // EVERY disk the vmid owns, including attached block-storage Volume disks
915	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
916	  // by that vmid, and both purge and the default destroy (which removes disks
917	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
918	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
919	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
920	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
921	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
922	  // can be re-attached after the reinstall. This runs BEFORE any status change or
923	  // destructive call, so a blocked reinstall touches nothing.
924	  //
925	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
926	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
927	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
928	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
929	  // let the worst path through: fill a volume, Detach (the UI says "Data is
930	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
931	  // Detaching is therefore NOT sufficient protection, and telling the customer to
932	  // detach was wrong advice; they must delete the volume (which destroys just
933	  // that disk, deliberately) or move it to another server first.
934	  const pinnedVolumes = await db.volume.findMany({
935	    where: { serverId: server.id },
936	  });
937	  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
938	  const realPinned = pinnedVolumes.filter(
939	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
940	  );
941	  if (realPinned.length > 0) {
942	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
943	    throw new Error(
944	      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
945	        `Reinstalling purges every disk this server owns — including detached volumes ` +
946	        `that are still assigned to it — and that cannot be undone.`
947	    );
948	  }
949	
950	  const { conn } = await nodeFor(server);
951	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
952	  if (server.vmid) await destroyVm(conn, server.vmid);
953	  await provision(job);
954	}
