994	      // the Virtual MAC + failover IP that suspend released back to the pool — that
995	      // IP may now belong to another server. Reconfigure onto shared NAT so it boots
996	      // with a valid, non-conflicting network instead of a dead public config.
997	      if (!reconfigured) {
