1179	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
1180	  const server = await loadServer(job);
1181	  const payload = (job.payload ?? {}) as { name?: string };
1182	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
1183	  if (!name) throw new Error("snapshot: invalid name");
1184	  if (SANDBOX) {
1185	    await notify(
1186	      server.userId,
1187	      `Snapshot ${op} (sandbox): ${name}`,
1188	      `Sandbox snapshot ${op} completed (no real VM was touched).`,
1189	      `/dashboard/servers/${server.id}`
1190	    );
1191	    return;
1192	  }
1193	  const { conn } = await nodeFor(server);
1194	  let upid: string;
1195	  if (op === "create") {
1196	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
1197	  } else if (op === "delete") {
1198	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
1199	  } else {
1200	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
1201	  }
1202	  await conn.waitForTask(upid, 600_000);
1203	  if (op === "rollback") {
1204	    // rollback leaves the VM stopped; bring it back if the server should be running
1205	    const current = await db.server.findUnique({ where: { id: server.id } });
1206	    if (current?.status === "RUNNING") {
1207	      try {
1208	        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
1209	        await conn.waitForTask(startUpid);
1210	      } catch { /* may already be running */ }
1211	
1212	      // Resync the root password. `rollback` puts the snapshot's OLD disk
1213	      // content back — including whatever /etc/shadow existed when it was
1214	      // taken — which can hold an older password than Server.rootPasswordEnc
1215	      // if a PASSWORD_RESET (or anything else) changed it since the snapshot
1216	      // was created. Left alone, every later SSH from the platform would
1217	      // authenticate with the DB's (now wrong) password against the guest's
1218	      // reverted (now correct-for-the-snapshot) one — the exact "All
1219	      // configured authentication methods failed" divergence documented on
1220	      // applyPasswordToGuest (lib/proxmox.ts) and on provision()'s password-
1221	      // reuse fix above. Best-effort: a failure here does not fail the
1222	      // rollback itself (the VM genuinely is back at the requested restore
1223	      // point) but is logged loudly since a stale password can otherwise look
1224	      // exactly like an unrelated SSH outage.
1225	      const pw = serverRootPassword(current ?? server);
1226	      if (pw && server.vmid) {
1227	        const ready = await waitForGuestAgent(conn, conn.node, server.vmid);
1228	        if (ready) {
1229	          const applied = await applyPasswordToGuest(conn, server.vmid, pw);
1230	          if (!applied) {
1231	            console.error(
1232	              `[worker] snapshot rollback: could not resync guest password for server ${server.id} (vmid ${server.vmid})`
1233	            );
1234	          }
1235	        } else {
1236	          console.error(
1237	            `[worker] snapshot rollback: guest agent never answered for server ${server.id} (vmid ${server.vmid}) — password may now be stale`
1238	          );
1239	        }
1240	      }
1241	    }
1242	  }
1243	}
