1315	/**
1316	 * Create one backup and PROVE it exists before saying so.
1317	 *
1318	 * INCIDENT H4 (2026-07-26 rehearsal): this handler gated only the vzdump task's
1319	 * exit status — it never checked that an archive was written, had no failure
1320	 * notification, and `Server.lastAutoBackup` was stamped by the SWEEP at enqueue
1321	 * time. A customer could read "Last automatic backup: today" every night for a
1322	 * month with nothing in storage, and find out at restore time.
1323	 *
1324	 * Now: snapshot the archive list before the run, re-read it after, and require a
1325	 * volid that was not there and is not empty (`freshBackupProof`). Only that
1326	 * writes `lastAutoBackup`. A failure notifies the customer with the reason and a
1327	 * command, rather than leaving a stale-but-cheerful timestamp behind.
1328	 */
1329	async function backupCreate(job: Job) {
1330	  const server = await loadServer(job);
1331	  if (SANDBOX) {
1332	    await sandboxAnimateJob(job.id, [
1333	      { pct: 5, step: "Starting" },
1334	      { pct: 25, step: "Creating archive… 25%" },
1335	      { pct: 55, step: "Creating archive… 55%" },
1336	      { pct: 80, step: "Creating archive… 80%" },
1337	      { pct: 95, step: "Finalizing" },
1338	      { pct: 100, step: "Backup complete" },
1339	    ]);
1340	    // Deliberately NOT stamping lastAutoBackup here: no archive exists, and the
1341	    // column means "a backup was observed in storage".
1342	    await notify(
1343	      server.userId,
1344	      `Backup simulated (sandbox) for ${server.hostname}`,
1345	      "Sandbox only — no VM was contacted and no archive was written. This is not a restore point.",
1346	      `/dashboard/servers/${server.id}`
1347	    );
1348	    return;
1349	  }
1350	  if (server.vmid == null) {
1351	    throw new Error("backup: this server has no VMID yet, so there is nothing to back up.");
1352	  }
1353	  const vmid = server.vmid;
1354	
1355	  try {
1356	    await reportJobProgress(job.id, 2, "Starting");
1357	    const { conn } = await nodeFor(server);
1358	
1359	    // Snapshot what already exists. Membership of this set — not a timestamp
1360	    // comparison — is what makes "a new archive appeared" unarguable: ctime comes
1361	    // off the hypervisor and our window would come off the worker's clock.
1362	    const before = await listBackupsOn(conn, vmid);
1363	
1364	    const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
1365	      vmid,
1366	      storage: "backup",
1367	      mode: "snapshot",
1368	      compress: "zstd",
1369	    });
1370	    await waitForTaskProgress(
1371	      conn,
1372	      upid,
1373	      (progress, step) => reportJobProgress(job.id, progress, step),
1374	      { timeoutMs: 3_600_000, phase: "backup" }
1375	    );
1376	
1377	    await reportJobProgress(job.id, 96, "Verifying archive");
1378	    const after = await listBackupsOn(conn, vmid);
1379	    const proof = freshBackupProof({ vmid, before, after });
1380	    if (!proof.proven) throw new Error(`backup not verified — ${proof.reason}`);
1381	
1382	    await reportJobProgress(job.id, 100, "Backup complete");
1383	
1384	    // Retention: keep the latest N backups for this server (N = the paid backup
1385	    // tier's keep count, an explicit backupKeep override winning); prune the rest.
1386	    const keep = resolveBackupKeep(server.backupTier, server.backupKeep);
1387	    try {
1388	      const pruned = await pruneBackups(conn, vmid, keep);
1389	      if (pruned > 0) console.log(`[backup] pruned ${pruned} old backup(s) for vmid ${vmid} (keep ${keep})`);
1390	    } catch (e) {
1391	      console.error(`[backup] prune failed for vmid ${vmid}`, e);
1392	    }
1393	
1394	    // The ONLY writer of lastAutoBackup, and only on proof.
1395	    await db.server.update({ where: { id: server.id }, data: { lastAutoBackup: new Date() } });
1396	
1397	    await notify(
1398	      server.userId,
1399	      `Backup completed for ${server.hostname}`,
1400	      `Verified present in backup storage: ${proof.volid} (${humanBytes(proof.sizeBytes)}).`,
1401	      `/dashboard/servers/${server.id}`
1402	    );
1403	  } catch (e: any) {
1404	    // Tell the customer it broke. Only on the final attempt, so the worker's
1405	    // three retries do not produce three notifications for one bad night.
1406	    if (job.attempts >= MAX_ATTEMPTS) {
1407	      await notify(
1408	        server.userId,
1409	        `Backup FAILED for ${server.hostname}`,
1410	        `${String(e?.message ?? e).slice(0, 400)} — this server has no new restore point. ` +
1411	          `Your last verified backup (if any) is shown under Backups.`,
1412	        `/dashboard/servers/${server.id}`
1413	      );
1414	    }
1415	    throw e;
1416	  }
1417	}
