1465	/**
1466	 * Refund a per-server disk expansion that was paid for but never delivered.
1467	 *
1468	 * The DISK_EXPAND handler advances `Server.extraDiskGB` only AFTER the disk has
1469	 * really grown, so that field is the ground truth for "did the customer get what
1470	 * they paid for". We refund only when it never reached the job's target — which
1471	 * also keeps this safe against the partial-success case (disk grown, filesystem
1472	 * left for the customer to grow by hand): that path completes successfully, sets
1473	 * extraDiskGB, and is therefore never refunded.
1474	 *
1475	 * Idempotent per job via the reconcile audit marker.
1476	 */
1477	async function reconcileFailedDiskExpand(job: Job) {
1478	  const p = (job.payload ?? {}) as { prorateCents?: number; addGB?: number; targetExtraDiskGB?: number };
1479	  const cents = p.prorateCents ?? 0;
1480	  if (cents <= 0 || !job.serverId) return;
1481	
1482	  const already = await db.auditLog.findFirst({
1483	    where: { action: "server.disk_expand.reconcile", detail: { contains: `job=${job.id}` } },
1484	  });
1485	  if (already) return;
1486	
1487	  const server = await db.server.findUnique({
1488	    where: { id: job.serverId },
1489	    select: { userId: true, hostname: true, extraDiskGB: true },
1490	  });
1491	  if (!server) return;
1492	
1493	  // The expansion actually landed (or a later one superseded it) — the customer
1494	  // has the storage, so the charge stands. Nothing to unwind.
1495	  const target = Number(p.targetExtraDiskGB ?? 0);
1496	  if (target > 0 && server.extraDiskGB >= target) return;
1497	
1498	  try {
1499	    await db.$transaction([
1500	      db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
1501	      db.walletTransaction.create({
1502	        data: {
1503	          userId: server.userId,
1504	          amountCents: cents,
1505	          description: `Refund: failed storage expansion (+${p.addGB ?? "?"} GB) — ${server.hostname}`,
1506	        },
1507	      }),
1508	      db.notification.create({
1509	        data: {
1510	          userId: server.userId,
1511	          title: `Storage expansion failed on ${server.hostname} — refunded`,
1512	          body: `We couldn't add the storage, so $${(cents / 100).toFixed(2)} has been credited back to your wallet. Your server and its data are untouched.`,
1513	          href: `/dashboard/servers/${job.serverId}`,
1514	        },
1515	      }),
1516	    ]);
1517	    await db.auditLog.create({
1518	      data: {
1519	        userId: server.userId,
1520	        action: "server.disk_expand.reconcile",
1521	        detail: `job=${job.id} addGB=${p.addGB} cents=${cents}`,
1522	      },
1523	    });
1524	  } catch (e: any) {
1525	    await db.auditLog
1526	      .create({
1527	        data: {
1528	          userId: server.userId,
1529	          action: "server.disk_expand.reconcile.uncharged",
1530	          detail: `job=${job.id} cents=${cents} :: ${e?.message ?? e}`,
1531	        },
1532	      })
1533	      .catch(() => {});
1534	  }
1535	}
