1537	/**
1538	 * Reverse a money side-effect that a job committed up-front but never delivered.
1539	 * Server actions charge/credit the wallet before enqueuing the worker job (so the
1540	 * UI reflects the change immediately); if the job then fails terminally the money
1541	 * must be unwound or the customer is charged for a resize that never happened
1542	 * (up) or keeps a downgrade credit for hardware they still have (down).
1543	 * Idempotent per job: guarded by the RECONCILED audit marker so a re-run can't
1544	 * double-reverse.
1545	 */
1546	async function reconcileFailedJob(job: Job) {
1547	  if (job.type === "DISK_EXPAND") return reconcileFailedDiskExpand(job);
1548	  if (job.type !== "RESIZE") return;
1549	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
1550	  const cents = p.prorateCents ?? 0;
1551	  if (cents <= 0 || !job.serverId) return;
1552	
1553	  // Idempotency: skip if we already reversed this exact job.
1554	  const already = await db.auditLog.findFirst({
1555	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
1556	  });
1557	  if (already) return;
1558	
1559	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
1560	  if (!server) return;
1561	
1562	  try {
1563	    if (p.direction === "up") {
1564	      // Upgrade charge never delivered → refund the prorated charge.
1565	      await db.$transaction([
1566	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
1567	        db.walletTransaction.create({
1568	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
1569	        }),
1570	      ]);
1571	    } else if (p.direction === "down") {
1572	      // Downgrade credit was given but hardware unchanged → claw the credit back.
1573	      // Guarded so it can never drive the balance negative; if the customer already
1574	      // spent it, we log and leave it (best-effort — they keep a small windfall).
1575	      await db.$transaction(async (tx) => {
1576	        await debitWallet(tx, server.userId, cents);
1577	        await tx.walletTransaction.create({
1578	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
1579	        });
1580	      });
1581	    }
1582	    await db.auditLog.create({
1583	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
1584	    });
1585	  } catch (e: any) {
1586	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
1587	    await db.auditLog.create({
1588	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
1589	    }).catch(() => {});
1590	  }
1591	}
