1593	async function runJob(job: Job) {
1594	  // The job is already atomically claimed (status RUNNING, attempts incremented)
1595	  // by the loop's compare-and-swap before we get here — see the CAS in main().
1596	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
1597	  try {
1598	    await handlers[job.type](job);
1599	    // Clear any error left over from an earlier failed attempt of THIS job. Without
1600	    // this, a job that failed once (error persisted, status QUEUED for retry) and
1601	    // then succeeded on a later attempt ends up DONE with a stale, misleading error
1602	    // still attached — indistinguishable from an actual silent failure to anyone
1603	    // reading Job.error (confirmed: a real PROVISION did exactly this today).
1604	    await db.job.update({ where: { id: job.id }, data: { status: "DONE", error: null } });
1605	    console.log(`[worker] job ${job.id} DONE`);
1606	  } catch (e: any) {
1607	    let error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`;
1608	    // Defense in depth: a child process (e.g. `sshpass -p <rootPassword> …`) can
1609	    // leak the server's root password into the thrown message. Redact it before
1610	    // it is persisted to Job.error. Redact BEFORE slicing so a truncation can't
1611	    // sever the match. Best-effort — never let redaction lookup fail the job path.
1612	    if (job.serverId) {
1613	      try {
1614	        const s = await db.server.findUnique({
1615	          where: { id: job.serverId },
1616	          select: { rootPassword: true, rootPasswordEnc: true },
1617	        });
1618	        const pw = s ? serverRootPassword(s) : null;
1619	        if (pw) error = error.split(pw).join("***");
1620	      } catch {
1621	        /* best-effort redaction */
1622	      }
1623	    }
1624	    error = error.slice(0, 2000);
1625	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
1626	    const current = await db.job.findUnique({ where: { id: job.id } });
1627	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
1628	    await db.job.update({
1629	      where: { id: job.id },
