1641	      }).catch(() => {});
1642	      if (job.serverId) {
1643	        const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
1644	        if (stillExists) {
1645	          // Only jobs that actually change the VM's run/disk state should strand the
