1710	    await db.job.update({
1711	      where: { id: job.id },
1712	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
1713	    });
1714	    if (!retriable) {
1715	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
1716	      if (job.serverId) {
