/**
 * Track player join/leave events by comparing the live RCON player list against
 * open PlayerSession rows (leftAt IS NULL). Runs every ~60s from the main loop.
 *
 * For each RUNNING game server with a gamePlan:
 *   - NEW players (in RCON but no open session) → create a PlayerSession
 *   - DEPARTED players (open session but not in RCON) → set leftAt = now()
 *   - STILL ONLINE → no-op
 *
 * Per-server try/catch so one unreachable VM never blocks the sweep.
 */
export async function playerTrackingSweep(): Promise<void> {
  if (SANDBOX) return;

  const servers = await db.server.findMany({
    where: { status: "RUNNING", gamePlanId: { not: null } },
    select: CONTROL_FIELDS,
  });

  const now = new Date();

  for (const server of servers) {
    try {
      const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
      if (!isGameFamily(fam)) continue;
      const spec = controlSpec(fam);
      if (!spec || spec.rcon !== "source" || !spec.listCommand) continue;

      // Get online players via RCON
      const res = await withServerSsh(server as SftpServer, (conn) =>
        runRcon(conn, spec, spec.listCommand!)
      );
      if (!res.ok) continue;
      const { players: onlinePlayers } = parsePlayers(spec.family, res.response);
      const onlineNames = new Set(onlinePlayers.map((p) => p.name.toLowerCase()));

      // Get open sessions for this server
      const openSessions = await db.playerSession.findMany({
        where: { serverId: server.id, leftAt: null },
      });
      const sessionByName = new Map(
        openSessions.map((s) => [s.playerName.toLowerCase(), s])
      );

      // NEW players: in RCON but no open session
      for (const p of onlinePlayers) {
        if (!sessionByName.has(p.name.toLowerCase())) {
          await db.playerSession.create({
            data: { serverId: server.id, playerName: p.name },
          });
        }
      }

      // DEPARTED players: open session but not in RCON
      for (const session of openSessions) {
        if (!onlineNames.has(session.playerName.toLowerCase())) {
          await db.playerSession.update({
            where: { id: session.id },
            data: { leftAt: now },
          });
        }
      }
    } catch (e) {
      // Per-server: one failure must not break the sweep
      console.error(`[player-tracking] sweep failed for server ${server.id}`, e);
    }
  }
}

