"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import {
  getPlayerHistory,
  getPlayerStats,
  type PlayerSessionRow,
  type PlayerStatsResult,
} from "@/lib/actions-game-control";

function formatDuration(ms: number): string {
  if (ms < 60_000) return "< 1m";
  const totalMin = Math.floor(ms / 60_000);
  const h = Math.floor(totalMin / 60);
  const m = totalMin % 60;
  if (h > 0) return m > 0 ? `${h}h ${m}m` : `${h}h`;
  return `${m}m`;
}

function formatDurationLong(ms: number): string {
  const totalMin = Math.floor(ms / 60_000);
  const h = Math.floor(totalMin / 60);
  const m = totalMin % 60;
  if (h > 0) return m > 0 ? `${h}h ${m}m` : `${h}h`;
  if (m > 0) return `${m}m`;
  return "< 1m";
}

function relativeTime(iso: string): string {
  const diff = Date.now() - new Date(iso).getTime();
  if (diff < 60_000) return "just now";
  const min = Math.floor(diff / 60_000);
  if (min < 60) return `${min}m ago`;
  const hr = Math.floor(min / 60);
  if (hr < 24) return `${hr}h ago`;
  const d = Math.floor(hr / 24);
  return `${d}d ago`;
}

export function GamePlayerHistory({ serverId }: { serverId: string }) {
  const [stats, setStats] = useState<Extract<PlayerStatsResult, { ok: true }> | null>(null);
  const [sessions, setSessions] = useState<PlayerSessionRow[]>([]);
  const [total, setTotal] = useState(0);
  const [search, setSearch] = useState("");
  const [appliedSearch, setAppliedSearch] = useState("");
  const [offset, setOffset] = useState(0);
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const PAGE_SIZE = 100;

  const loadStats = useCallback(() => {
    start(async () => {
      const r = await getPlayerStats(serverId);
      if (r.ok) setStats(r);
      else setErr(r.error);
    });
  }, [serverId]);

  const loadHistory = useCallback(
    (searchVal: string, off: number) => {
      start(async () => {
        const r = await getPlayerHistory(serverId, {
          limit: PAGE_SIZE,
          offset: off,
          playerName: searchVal || undefined,
        });
        if (r.ok) {
          setSessions(off === 0 ? r.sessions : (prev) => [...prev, ...r.sessions]);
          setTotal(r.total);
          setErr(null);
        } else {
          setErr(r.error);
        }
      });
    },
    [serverId]
  );

  useEffect(() => {
    loadStats();
    loadHistory("", 0);
  }, [loadStats, loadHistory]);

  function doSearch() {
    const val = search.trim();
    setAppliedSearch(val);
    setOffset(0);
    setSessions([]);
    loadHistory(val, 0);
  }

  function loadMore() {
    const newOffset = offset + PAGE_SIZE;
    setOffset(newOffset);
    loadHistory(appliedSearch, newOffset);
  }

  return (
    <div className="space-y-5">
      {/* Stats overview */}
      {stats && (
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
          <StatCard label="Unique players" value={String(stats.uniquePlayers)} />
          <StatCard label="Online now" value={String(stats.currentOnline)} highlight />
          <StatCard label="Total playtime" value={formatDurationLong(stats.totalPlaytimeMs)} />
          <StatCard label="Avg session" value={stats.avgSessionMs > 0 ? formatDurationLong(stats.avgSessionMs) : "--"} />
        </div>
      )}

      {/* Top players */}
      {stats && stats.topPlayers.length > 0 && (
        <div className="card">
          <h3 className="font-semibold">Top players</h3>
          <p className="mt-0.5 text-sm text-slate-400">By total playtime</p>
          <ul className="mt-4 divide-y divide-white/[0.06]">
            {stats.topPlayers.map((p, i) => (
              <li key={p.name} className="flex items-center justify-between gap-3 py-2.5">
                <span className="flex items-center gap-2.5 text-sm">
                  <span className="flex h-8 w-8 items-center justify-center rounded-full bg-gradient-to-br from-brand-500/40 to-accent-blue/30 text-[11px] font-bold text-white">
                    {i + 1}
                  </span>
                  <span className="font-medium text-slate-100">{p.name}</span>
                </span>
                <span className="text-sm text-slate-400">
                  {formatDurationLong(p.totalMs)} · {p.sessions} session{p.sessions !== 1 ? "s" : ""}
                </span>
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Session log */}
      <div className="card">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h3 className="font-semibold">Session log</h3>
            <p className="mt-0.5 text-sm text-slate-400">{total} session{total !== 1 ? "s" : ""} recorded</p>
          </div>
          <div className="flex gap-2">
            <input
              className="input w-48"
              placeholder="Filter by player..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && doSearch()}
            />
            <button
              className="btn-primary text-sm"
              onClick={doSearch}
              disabled={pending}
            >
              Search
            </button>
          </div>
        </div>

        {err && <p className="mt-3 text-sm text-amber-300">{err}</p>}

        {sessions.length === 0 && !pending && !err ? (
          <p className="mt-4 text-sm text-slate-500">
            {appliedSearch ? "No sessions found for this player." : "No player sessions recorded yet. Sessions are tracked automatically while the server is running."}
          </p>
        ) : (
          <>
            {/* Table header - desktop */}
            <div className="mt-4 hidden text-xs font-medium uppercase tracking-wide text-slate-500 sm:grid sm:grid-cols-[1fr_1fr_1fr_auto]">
              <span>Player</span>
              <span>Joined</span>
              <span>Left</span>
              <span className="text-right">Duration</span>
            </div>

            <ul className="mt-2 divide-y divide-white/[0.06] sm:mt-1">
              {sessions.map((s) => {
                const isOnline = !s.leftAt;
                const duration = s.durationMs
                  ? formatDuration(s.durationMs)
                  : isOnline
                  ? formatDuration(Date.now() - new Date(s.joinedAt).getTime())
                  : "--";

                return (
                  <li key={s.id} className="py-2.5 sm:grid sm:grid-cols-[1fr_1fr_1fr_auto] sm:items-center">
                    {/* Player name */}
                    <span className="flex items-center gap-2.5 text-sm">
                      <span className="flex h-8 w-8 items-center justify-center rounded-full bg-gradient-to-br from-brand-500/40 to-accent-blue/30 text-[11px] font-bold text-white">
                        {s.playerName.slice(0, 2).toUpperCase()}
                      </span>
                      <span className="font-medium text-slate-100">{s.playerName}</span>
                      {isOnline && (
                        <span className="flex items-center gap-1 rounded-full bg-emerald-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-emerald-400">
                          <span className="h-2 w-2 rounded-full bg-emerald-400" />
                          Online
                        </span>
                      )}
                    </span>

                    {/* Joined */}
                    <span className="mt-1 block text-sm text-slate-400 sm:mt-0">
                      <span className="text-slate-500 sm:hidden">Joined </span>
                      {relativeTime(s.joinedAt)}
                    </span>

                    {/* Left */}
                    <span className="mt-0.5 block text-sm text-slate-400 sm:mt-0">
                      {isOnline ? (
                        <span className="text-emerald-400">Online now</span>
                      ) : (
                        <>
                          <span className="text-slate-500 sm:hidden">Left </span>
                          {relativeTime(s.leftAt!)}
                        </>
                      )}
                    </span>

                    {/* Duration */}
                    <span className="mt-0.5 block text-right text-sm text-slate-400 sm:mt-0">
                      <span className="text-slate-500 sm:hidden">Duration: </span>
                      {duration}
                    </span>
                  </li>
                );
              })}
            </ul>

            {sessions.length < total && (
              <div className="mt-4 text-center">
                <button
                  className="text-sm text-slate-400 hover:text-white disabled:opacity-40"
                  onClick={loadMore}
                  disabled={pending}
                >
                  {pending ? "Loading..." : `Load more (${total - sessions.length} remaining)`}
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

function StatCard({ label, value, highlight }: { label: string; value: string; highlight?: boolean }) {
  return (
    <div className="card flex flex-col items-center justify-center py-4 text-center">
      <p className={`text-2xl font-bold ${highlight ? "text-emerald-400" : "text-white"}`}>{value}</p>
      <p className="mt-1 text-xs text-slate-400">{label}</p>
    </div>
  );
}

